# POST /api/sheets/{sheetId}/claims/{claimId}/status — move a claim to a new status (body
# {status, user, review, reason}): DRAFT to OPEN, OPEN to SETTLED, DRAFT, OPEN or PENDING to VOID,
# and SETTLED to VOID by a steward within 7 days of its settling (its status log's SETTLED date); DRAFT
# to DELETED (deleted: it counts nowhere), and DELETED back to DRAFT (restored) only on the sheet's today it
# was deleted on (its status log's last DELETED date).
# A clerk (any user not assigned steward) settling a claim whose due is above the sheet's clerk limit
# sends it to PENDING instead. A steward reviews a PENDING claim (review true): status SETTLED approves
# it (not by the user who opened it or last edited it), status OPEN with a reason rejects it. Refused (400) for any
# other change, when the sheet's permission matrix (perm-open, perm-settle, perm-void; by default a
# clerk or a steward) does not allow the user's role to open, settle or void, when settling or approving a claim with no proofs whose due is above the proof threshold
# in force on its date, when opening a claim with an empty note whose due is above the note threshold
# in force on its date (both checked before the clerk limit, so it never goes to PENDING), when the user who opened the claim or last edited it (claim form or amount entry) tries to settle or approve it, when the claim is not on
# the sheet, or when its due-by falls in a closed period, or when opening a DRAFT whose due-by falls in a period
# with a cap while its person already has that many OPEN or PENDING claims due in it; nothing is stored then. Opening records the
# user as the claim's opened-by; a claim whose due is above the review threshold in force on its date goes to REVIEW (no
# number yet, CLAIM_REVIEW) instead of OPEN, and only a steward's review (status OPEN, review true) moves it on: CLAIM_REVIEWED,
# then CLAIM_OPENED with its number. A REVIEW claim may otherwise only be voided.
# A stored change is recorded in the audit file as CLAIM_OPENED,
# CLAIM_PENDING, CLAIM_SETTLED, CLAIM_APPROVED, CLAIM_REJECTED, CLAIM_VOIDED, CLAIM_DELETED or CLAIM_RESTORED (with reversed=<the
# frozen figure> when a SETTLED claim is voided). While the sheet has void reasons, a void needs one of
# them as its reason (refused otherwise); it is kept on the claim and CLAIM_VOIDED ends with reason=<it>.
validate:
  class: net.officefloor.hq.app.claim.ValidateStatus
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: checkLimit
checkLimit:
  class: net.officefloor.hq.app.claim.CheckClerkLimit
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyStatus
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimStatus
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/bulk-open — open the selected claims together (body {claimIds, user}).
# Each selected claim that can be opened (a DRAFT on the sheet, not due by a date in a closed period, nor in a capped period its person already has that many OPEN or
# PENDING claims in, with a note or a due not above the note threshold in force on
# its date) is
# opened and numbered in list order — people by their positions, a person's claims
# newest first — and recorded as CLAIM_OPENED, as a single open is; each that cannot is refused and
# left as it is. Answers {opened, refused}. Refused (400) only when no claim is selected.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkOpen
  next: open
open:
  class: net.officefloor.hq.app.claim.OpenClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/paste-claims — add a DRAFT claim per pasted line, in order (body: {text,
# user}). Each line is name,amount,date,note: the name must be on the sheet (ignoring case and the
# spaces around it), the date may be blank for the sheet's today, the note may hold commas or be
# absent. A note ending in " #<ref>" gives the claim that external reference (not part of the note);
# a reference used on the sheet or earlier in the paste, without regard to case, refuses the paste. Every line is first checked with the claim form's rules; refused (400), storing nothing and
# recording nothing, when any line fails or there is no line. A line naming a person, date and note
# that match one of their claims as they stood before the paste (void and deleted ones aside; never a
# claim an earlier line added) updates the newest such DRAFT instead: edited to the line's amount
# (CLAIM_EDITED when it changes); a line whose matches include no DRAFT refuses the paste. Then, in
# paste order, each claim is added (CLAIM_ADDED, as a single add is) or edited, and opened by the user
# exactly as the open button would (numbered, CLAIM_OPENED with the rollup lines). Any refusal the add,
# edit or open would give refuses the whole paste, storing and recording nothing. Answers {added}: how
# many lines went through.
validate:
  class: net.officefloor.hq.app.paste.ValidatePaste
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.paste.SavePasted
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.paste.RespondWithPaste
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Works out the move a status change makes. Opening a DRAFT whose due is above the review threshold in
 *  force on its date sends it to REVIEW instead; only a steward's review moves a REVIEW claim on, to OPEN,
 *  and otherwise it may only be voided. A clerk settling an OPEN claim whose due is above the
 *  sheet's clerk limit sends it to PENDING instead. A claim whose due is n/a is within any limit; a
 *  sheet with no limit, and a steward, settle anything. Only a steward reviews a PENDING claim, and
 *  only a review moves it to SETTLED or back to OPEN; a review of a claim that is not PENDING is refused.
 *  Before the limit is considered, settling or approving a claim with no proofs whose due is above the
 *  proof threshold is refused (see {@link CheckProofs}), so it never goes to PENDING. Opening, settling
 *  and voiding are refused to a role the sheet's permission matrix does not allow it. A SETTLED claim
 *  may be voided only by a steward, and only within {@link #VOID_SETTLED_DAYS} days of the sheet's today
 *  it was settled on (its status log's SETTLED date). A DELETED claim may be restored only on the
 *  sheet's today it was deleted on. */
public class CheckClerkLimit {
    /** How many days after settling a claim a steward may still void it. */
    static final int VOID_SETTLED_DAYS = 7;

    public void check(@Val StatusInput input, @Val Claim claim, RoleStore roles, SettingStore settings,
            PersonStore people, RateStore rates, SheetStore sheets, ClaimStore claims, ClaimLogStore log,
            Out<StatusMove> move)
            throws InvalidSheetException {
        ClaimStatus from = claim.getStatus();
        Role role = roles.find(claim.getSheetId(), input.user());
        boolean steward = role == Role.STEWARD;
        if (input.review() && from == ClaimStatus.REVIEW) {
            if (!steward) {
                throw new InvalidSheetException("Only a steward can review a claim");
            }
            if (input.status() != ClaimStatus.OPEN) {
                throw new InvalidSheetException("A review makes a REVIEW claim OPEN");
            }
            move.set(new StatusMove(from, ClaimStatus.OPEN));
            return;
        }
        if (input.review()) {
            if (from != ClaimStatus.PENDING) {
                throw new InvalidSheetException("Only a PENDING claim can be approved or rejected");
            }
            if (!steward) {
                throw new InvalidSheetException("Only a steward can approve or reject a claim");
            }
            if (input.status() == ClaimStatus.OPEN && input.reason().isEmpty()) {
                throw new InvalidSheetException("A rejection needs a reason");
            }
            CheckProofs.refuseUnproved(input, claim, settings, people, rates, sheets, claims);
            move.set(new StatusMove(from, input.status()));
            return;
        }
        if (from == ClaimStatus.PENDING && input.status() != ClaimStatus.VOID) {
            throw new InvalidSheetException("A PENDING claim waits for a steward to approve or reject it");
        }
        if (from == ClaimStatus.REVIEW && input.status() != ClaimStatus.VOID) {
            throw new InvalidSheetException("A REVIEW claim waits for a steward to review it");
        }
        refuseUnpermitted(input.status(), claim.getSheetId(), role, settings);
        if (from == ClaimStatus.SETTLED && input.status() == ClaimStatus.VOID) {
            refuseLateVoid(claim, steward, log, sheets);
        }
        if (from == ClaimStatus.DELETED && input.status() == ClaimStatus.DRAFT) {
            refuseLateRestore(claim, log, sheets);
        }
        if (from == ClaimStatus.DRAFT && input.status() == ClaimStatus.OPEN) {
            CheckProofs.refuseUnnoted(claim, settings, people, rates, sheets, claims);
        }
        CheckProofs.refuseUnproved(input, claim, settings, people, rates, sheets, claims);
        ClaimStatus to = overLimit(input, claim, steward, settings, people, rates, sheets, claims)
                ? ClaimStatus.PENDING : input.status();
        if (from == ClaimStatus.DRAFT && to == ClaimStatus.OPEN
                && overReview(claim, settings, people, rates, sheets, claims)) {
            to = ClaimStatus.REVIEW;
        }
        move.set(new StatusMove(from, to));
    }

    /** Whether opening the claim sends it to REVIEW: its due is above the review threshold in force on its
     *  date. A sheet with no threshold then, and a claim whose due is n/a, open as OPEN. */
    static boolean overReview(Claim claim, SettingStore settings, PersonStore people, RateStore rates,
            SheetStore sheets, ClaimStore claims) {
        BigDecimal threshold = settings.reviewThreshold(claim.getSheetId(), claim.getDate());
        if (threshold == null) {
            return false;
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        BigDecimal pct = person == null ? null : rates.forClaim(claim).find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
        BigDecimal due = Lateness.of(claim.getSheetId(), settings, sheets, claims, people).due(claim, pct);
        return due != null && due.compareTo(threshold) > 0;
    }

    /** Refuses voiding a SETTLED claim by anyone but a steward, or later than {@link #VOID_SETTLED_DAYS}
     *  days after it was settled. */
    static void refuseLateVoid(Claim claim, boolean steward, ClaimLogStore log, SheetStore sheets)
            throws InvalidSheetException {
        if (!steward) {
            throw new InvalidSheetException("Only a steward can void a SETTLED claim");
        }
        LocalDate settled = log.settledOn(claim);
        LocalDate today = sheets.today(claim.getSheetId());
        if (settled == null || today == null || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
            throw new InvalidSheetException("A SETTLED claim can be voided only within " + VOID_SETTLED_DAYS
                    + " days of settling it");
        }
    }

    /** Refuses restoring a DELETED claim on any day but the sheet's today it was deleted on (its status
     *  log's last DELETED date). */
    static void refuseLateRestore(Claim claim, ClaimLogStore log, SheetStore sheets) throws InvalidSheetException {
        LocalDate deleted = log.lastOn(claim, ClaimStatus.DELETED);
        LocalDate today = sheets.today(claim.getSheetId());
        if (deleted == null || today == null || !today.equals(deleted)) {
            throw new InvalidSheetException("A DELETED claim can be restored only on the day it was deleted");
        }
    }

    /** Refuses opening, settling or voiding a claim by a role the sheet's permission matrix does not allow it. */
    static void refuseUnpermitted(ClaimStatus to, String sheetId, Role role, SettingStore settings)
            throws InvalidSheetException {
        String action = to == ClaimStatus.OPEN ? "open" : to == ClaimStatus.SETTLED ? "settle"
                : to == ClaimStatus.VOID ? "void" : null;
        if (action != null && !settings.allows(sheetId, action, role)) {
            throw new InvalidSheetException("A " + role.shown() + " may not " + action + " a claim");
        }
    }

    private static boolean overLimit(StatusInput input, Claim claim, boolean steward, SettingStore settings,
            PersonStore people, RateStore rates, SheetStore sheets, ClaimStore claims) {
        if (input.status() != ClaimStatus.SETTLED || claim.getStatus() != ClaimStatus.OPEN || steward) {
            return false;
        }
        BigDecimal limit = settings.clerkLimit(claim.getSheetId());
        if (limit == null) {
            return false;
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        BigDecimal pct = person == null ? null : rates.forClaim(claim).find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
        BigDecimal due = Lateness.of(claim.getSheetId(), settings, sheets, claims, people).due(claim, pct);
        return due != null && due.compareTo(limit) > 0;
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Opens each selected claim that can be opened, in list order: its people in the order they were
 *  added, a person's claims newest first. Each is opened as a single open would be (its next
 *  number, opened-by the user) and recorded as CLAIM_OPENED, then how it moved the sheet's figures; one whose
 *  due is above the review threshold in force on its date goes to REVIEW instead (CLAIM_REVIEW, no number yet),
 *  counted as opened.
 *  A claim that is not on the sheet, is not a DRAFT, or is due by a date in a closed period, or whose person already has
 *  as many OPEN or PENDING claims in its period as the period's cap (counting those opened before it here), or has an empty note while its due is above the
 *  note threshold in force on its date, and every claim when
 *  the sheet is archived or the sheet's permission matrix does not allow the user's role to open, is refused and
 *  left as it is. */
public class OpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenInput input, ClaimStore store,
            PersonStore people, PeriodStore periods, SettingStore settings, SheetStore sheets, RoleStore roles, RateStore rates, ClaimLogStore log, RollupService rollups, Audit audit, Out<BulkOpenResult> result) {
        String sheet = sheetId.trim();
        Map<Long, Integer> personOrder = new HashMap<>();
        Map<Long, Person> persons = new HashMap<>();
        // A person's claims newest first, as listed: a claim moved to them is listed as their newest.
        Map<Long, Integer> listed = new HashMap<>();
        for (Claim claim : store.list(sheet)) {
            listed.put(claim.getId(), listed.size());
        }
        for (Person person : people.list(sheet)) {
            personOrder.put(person.getId(), personOrder.size());
            persons.put(person.getId(), person);
        }
        int refused = 0;
        List<Claim> selected = new ArrayList<>();
        for (Long id : input.claimIds()) {
            Claim claim = id == null ? null : store.find(sheet, id);
            if (claim == null) {
                refused++;
            } else {
                selected.add(claim);
            }
        }
        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                .thenComparing(c -> listed.getOrDefault(c.getId(), Integer.MAX_VALUE)));
        boolean permitted = !sheets.archived(sheet) && settings.allows(sheet, "open", roles.find(sheet, input.user()));
        int opened = 0;
        for (Claim claim : selected) {
            if (!permitted || claim.getStatus() != ClaimStatus.DRAFT || closed(periods, claim)
                    || capped(periods, store, claim) || unnoted(claim, settings, people, rates, sheets, store)) {
                refused++;
                continue;
            }
            Rollup before = rollups.snapshot(sheet);
            ClaimStatus to = CheckClerkLimit.overReview(claim, settings, people, rates, sheets, store)
                    ? ClaimStatus.REVIEW : ClaimStatus.OPEN;
            if (!store.move(claim, claim.getStatus(), to)) {
                refused++;
                continue;
            }
            claim.setStatus(to);
            if (to == ClaimStatus.OPEN) {
                claim.setNumber(Numbering.next(sheet, claim.getDueBy(), store, settings, sheets, periods));
            }
            claim.setOpenedBy(input.user());
            store.save(claim);
            if (to == ClaimStatus.REVIEW) {
                store.markReview(claim, sheets.today(sheet));
            }
            log.record(claim, input.user());
            Person person = persons.get(claim.getPersonId());
            ClaimResponse shown = ClaimResponse.from(claim);
            audit.record(to.event() + " sheet=" + sheet + " by=" + input.user() + " person="
                    + (person == null ? "" : person.getName()) + " amount=" + shown.amount() + " date=" + shown.date()
                    + (to == ClaimStatus.OPEN ? " number=" + claim.getNumber() : ""));
            rollups.record(sheet, input.user(), before);
            opened++;
        }
        result.set(new BulkOpenResult(opened, refused));
    }

    private static boolean unnoted(Claim claim, SettingStore settings, PersonStore people, RateStore rates,
            SheetStore sheets, ClaimStore store) {
        try {
            CheckProofs.refuseUnnoted(claim, settings, people, rates, sheets, store);
            return false;
        } catch (InvalidSheetException e) {
            return true;
        }
    }

    private static boolean capped(PeriodStore periods, ClaimStore store, Claim claim) {
        try {
            ClaimPeriods.refuseCapped(periods, store, claim);
            return false;
        } catch (InvalidSheetException e) {
            return true;
        }
    }

    private static boolean closed(PeriodStore periods, Claim claim) {
        try {
            ClaimPeriods.refuseClosed(periods, claim.getSheetId(), claim.getDueBy());
            return false;
        } catch (InvalidSheetException e) {
            return true;
        }
    }
}

