   * Stores the person over the version it was loaded at, moving the version on; false (nothing
   * stored) when someone else has stored another version since. The grade the edit records (if any)
   * is kept with the ones already recorded, replacing one from the same date.
   */
  public boolean save(Person person) {
      int n = jdbc.update(
              "UPDATE person SET name = ?, terms = ?, contact = ?, tags = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
              person.getName(), person.getTerms(), person.getContact(), person.getTags(), person.getSheetId(), person.getId(), person.getVersion());
      if (n == 1) {
          person.setVersion(person.getVersion() + 1);
          LocalDate from = person.getRecordFrom();
          if (from != null) {
              jdbc.update("MERGE INTO person_grade (sheet_id, person_id, from_date, grade) KEY (person_id, from_date)"
                      + " VALUES (?, ?, ?, ?)", person.getSheetId(), person.getId(), from, person.getGrades().get(from));
          }
          LocalDate termsFrom = person.getTermsRecordFrom();
          if (termsFrom != null) {
              recordTerms(person, termsFrom);
          }
      }
      return n == 1;
  }

  /** Stores the person's dated terms from the date, replacing any from the same date. */
  public void recordTerms(Person person, LocalDate from) {
      jdbc.update("MERGE INTO person_terms (sheet_id, person_id, from_date, terms) KEY (person_id, from_date)"
              + " VALUES (?, ?, ?, ?)", person.getSheetId(), person.getId(), from, person.getDatedTerms().get(from));
  }

